import test from 'node:test';import assert from 'node:assert/strict';
import {Game,freshProfile,SKILLS} from '../src/domain/game.js';
test('endless ignores every permanent upgrade and never mutates the original profile',()=>{const p=freshProfile();for(const key of ['stock','normal','start','bonus','supply','tickets'])p.upgrades[key]=5;const before=structuredClone(p),g=new Game(p,2,()=>.5,{endless:true});assert.equal(g.stock,400);assert.deepEqual(g.profile.upgrades,freshProfile().upgrades);g.stage=10;g.award(g.target+10);g.checkStage();assert.equal(g.phase,'skill');g.selectSkill(g.choices[0].id);assert.equal(g.stage,11);assert.equal(g.progress,0);assert.ok(g.target>g.stock);g.finish('lost');assert.equal(g.result.tickets,0);assert.equal(g.result.endless,true);assert.deepEqual(p,before);});
test('endless continues when all skills are maxed; zero balls still ends the run',()=>{const g=new Game(freshProfile(),0,()=>.5,{endless:true});for(const s of SKILLS)g.skills[s.id]=5;g.stage=101;g.setStock(g.target);g.checkStage();assert.equal(g.choices.length,0);g.selectSkill(null);assert.equal(g.stage,102);assert.equal(g.phase,'playing');g.stock=0;g.tick(3);assert.equal(g.phase,'result');assert.equal(g.result.tickets,0);});
